//! Test vectors copied from RFC 8448, "Example Handshake Traces for TLS 1.3"
//! (January 2019, <https://www.rfc-editor.org/rfc/rfc8448>, plain text as served
//! by rfc-editor.org). The text has no commit to pin (an RFC is immutable) and is
//! not vendored under `tests/data/`, whose rules need a commit, so the vectors are
//! Rust literals; each entry names the section and the line of the RFC's text file
//! (`rfc8448.txt`, 3811 lines) its hex starts on. Sections: 3 simple 1-RTT, 4
//! resumed 0-RTT, 5 HelloRetryRequest, 6 client authentication, 7 compatibility mode.
//!
//! Generated once from the RFC text by a script that is not part of the repository:
//! every entry's octet count was checked against the count the RFC states.

/// One handshake message ("construct a ... handshake message").
pub struct Message {
    /// RFC 8448 section number.
    pub section: u8,
    /// Line of `rfc8448.txt` where the hex starts.
    pub line: u32,
    /// `client` or `server`.
    pub actor: &'static str,
    /// The RFC's name for the message.
    pub name: &'static str,
    /// The message as hex.
    pub hex: &'static str,
}

/// One record ("send ... record"): the payload the RFC gives (the plaintext content, with no
/// content type or padding for an encrypted record) and the complete record on the wire.
pub struct Record {
    /// RFC 8448 section number.
    pub section: u8,
    /// Line where the payload's hex starts.
    pub payload_line: u32,
    /// Line where the complete record's hex starts.
    pub record_line: u32,
    /// `client` or `server`.
    pub actor: &'static str,
    /// The RFC's step, e.g. `send handshake record:`.
    pub step: &'static str,
    /// The payload as hex.
    pub payload: &'static str,
    /// The complete record as hex.
    pub record: &'static str,
}

